function registerVetStatsOverviewHandlers(prisma2) {
  ipcMain.handle("vet:stats:overview", async (_e, period) => {
    try {
      const now = /* @__PURE__ */ new Date();
      const start = new Date(now);
      switch (period ?? "month") {
        case "today":
          start.setHours(0, 0, 0, 0);
          break;
        case "week":
          start.setDate(now.getDate() - 7);
          start.setHours(0, 0, 0, 0);
          break;
        case "month":
          start.setDate(1);
          start.setHours(0, 0, 0, 0);
          break;
        case "year":
          start.setMonth(0, 1);
          start.setHours(0, 0, 0, 0);
          break;
      }
      const [totalPatients, newPatients, sessionRows, outstandingRows, upcomingAppts, medSaleRows] = await Promise.all([
        prisma2.vetPatient.count(),
        prisma2.vetPatient.count({ where: { createdAt: { gte: start } } }),
        prisma2.$queryRawUnsafe(`
          SELECT
            COUNT(*) as sessionCount,
            COALESCE(SUM(amountCharged),0) as revenue,
            COALESCE(SUM(amountPaid),0) as collected
          FROM VetSession
          WHERE visitDate >= ?
        `, start),
        prisma2.$queryRawUnsafe(`
          SELECT COALESCE(SUM(amountCharged),0) - COALESCE(SUM(amountPaid),0) as outstanding
          FROM VetSession WHERE paymentStatus NOT IN ('paid','waived')
        `),
        prisma2.vetAppointment.count({
          where: {
            appointmentDate: { gte: now },
            status: { in: ["scheduled", "confirmed"] }
          }
        }),
        prisma2.$queryRawUnsafe(`
          SELECT
            COUNT(*)                                                  as saleCount,
            COALESCE(SUM(${SQL_NET_REVENUE}), 0)                      as medicineRevenue,
            COALESCE(SUM(${SQL_COGS}), 0)                             as medicineCost
          FROM VetMedicineSale s
          JOIN VetMedicineBatch b ON s.batchId = b.id
          JOIN VetMedicine m      ON s.medicineId = m.id
          WHERE s.saleDate >= ?
        `, start)
      ]);
      const medicineRevenue = Number(medSaleRows[0]?.medicineRevenue) || 0;
      const medicineCost = Number(medSaleRows[0]?.medicineCost) || 0;
      return {
        totalPatients,
        newPatients,
        sessionCount: Number(sessionRows[0]?.sessionCount) || 0,
        revenue: Number(sessionRows[0]?.revenue) || 0,
        collected: Number(sessionRows[0]?.collected) || 0,
        outstanding: Number(outstandingRows[0]?.outstanding) || 0,
        upcomingAppts,
        medicineRevenue,
        medicineCost,
        medicineProfit: medicineRevenue - medicineCost,
        medicineSales: Number(medSaleRows[0]?.saleCount) || 0
      };
    } catch (err) {
      log94.error("overview", err);
      throw err;
    }
  });
}

// src/plugins/vet/handlers/stats.clinical.ts
init_electron_node();
var log95 = createLogger("Vet:Stats:Clinical");
function registerVetStatsClinicalHandlers(prisma2) {
  ipcMain.handle("vet:stats:topDiagnoses", async (_e, params) => {
    try {
      const limit = params?.limit ?? 10;
      const from = params?.from ? new Date(params.from) : new Date((/* @__PURE__ */ new Date()).getFullYear(), (/* @__PURE__ */ new Date()).getMonth() - 2, 1);
      const rows = await prisma2.$queryRawUnsafe(`
        SELECT diagnosis, COUNT(*) as cnt
        FROM VetSession
        WHERE diagnosis IS NOT NULL AND diagnosis != '' AND visitDate >= ?
        GROUP BY diagnosis
        ORDER BY cnt DESC
        LIMIT ?
      `, from, limit);
      return rows.map((r) => ({ diagnosis: r.diagnosis, count: Number(r.cnt) }));
    } catch (err) {
      log95.error("topDiagnoses", err);
      throw err;
    }
  });
  ipcMain.handle("vet:stats:visitTrend", async (_e, params) => {
    try {
      const now = /* @__PURE__ */ new Date();
      const from = params?.from ? new Date(params.from) : new Date(now.getFullYear(), now.getMonth() - 2, 1);
      const to = params?.to ? new Date(params.to) : now;
      const rows = await prisma2.$queryRawUnsafe(`
        SELECT visitType,
               COUNT(*) as cnt,
               COALESCE(SUM(amountCharged), 0) as revenue,
               COALESCE(SUM(amountPaid), 0)    as collected
        FROM VetSession WHERE visitDate >= ? AND visitDate <= ?
        GROUP BY visitType
        ORDER BY cnt DESC
      `, from, to);
      return rows.map((r) => {
        const count = Number(r.cnt);
        const revenue = Number(r.revenue);
        return {
          visitType: r.visitType,
          count,
          revenue,
          collected: Number(r.collected),
          avg: count > 0 ? revenue / count : 0
        };
      });
    } catch (err) {
      log95.error("visitTrend", err);
      throw err;
    }
  });
  ipcMain.handle("vet:stats:speciesBreakdown", async () => {
    try {
      const rows = await prisma2.$queryRawUnsafe(`
        SELECT species, COUNT(*) as cnt FROM VetPatient GROUP BY species ORDER BY cnt DESC
      `);
      return rows.map((r) => ({ species: r.species, count: Number(r.cnt) }));
    } catch (err) {
      log95.error("speciesBreakdown", err);
      throw err;
    }
  });
  ipcMain.handle("vet:stats:monthlyTrend", async (_e, params) => {
    try {
      const months = params?.months ?? 6;
      const rows = await prisma2.$queryRawUnsafe(`
        SELECT
          strftime('%Y-%m', visitDate) as ym,
          COALESCE(SUM(amountCharged),0) as revenue,
          COALESCE(SUM(amountPaid),0) as collected,
          COUNT(*) as sessions
        FROM VetSession
        WHERE visitDate >= date('now', '-' || ? || ' months')
        GROUP BY ym
        ORDER BY ym ASC
      `, months);
      return rows.map((r) => ({
        month: r.ym,
        revenue: Number(r.revenue) || 0,
        collected: Number(r.collected) || 0,
        sessions: Number(r.sessions) || 0
      }));
    } catch (err) {
      log95.error("monthlyTrend", err);
      throw err;
    }
  });
}

// src/plugins/vet/handlers/stats.sales.ts
init_electron_node();
var log96 = createLogger("Vet:Stats:Sales");
function registerVetStatsSalesHandlers(prisma2) {
  ipcMain.handle("vet:stats:profitAnalysis", async (_e, params) => {
    try {
      const now = /* @__PURE__ */ new Date();
      const from = params?.from ? new Date(params.from) : new Date(now.getFullYear(), now.getMonth(), 1);
      const to = params?.to ? new Date(params.to) : now;
      const EQTY = SQL_SOLD_QTY;
      const LISTED = `COALESCE(b.sellingPrice,
                       CASE WHEN s.saleUnit='sub' AND m.subUnitsPerContainer>0
                            THEN s.unitPrice*m.subUnitsPerContainer ELSE s.unitPrice END)`;
      const ACTUAL = SQL_NET_REVENUE;
      const soldRows = await prisma2.$queryRawUnsafe(`
        SELECT
          COUNT(*)                                              as saleCount,
          CAST(COALESCE(SUM(${EQTY}), 0)            AS REAL)    as unitsSold,
          CAST(COALESCE(SUM(${ACTUAL}), 0)         AS REAL)    as actualRevenue,
          CAST(COALESCE(SUM(${EQTY} * ${LISTED}), 0) AS REAL)  as expectedRevenue,
          CAST(COALESCE(SUM(${EQTY} * b.costPerUnit), 0) AS REAL) as cogs
        FROM VetMedicineSale s
        JOIN VetMedicineBatch b ON s.batchId = b.id
        JOIN VetMedicine m      ON s.medicineId = m.id
        WHERE s.saleDate >= ? AND s.saleDate <= ?
          AND (s.status IS NULL OR s.status != 'refunded')
      `, from, to);
      const invRows = await prisma2.$queryRawUnsafe(`
        SELECT
          CAST(COALESCE(SUM(b.quantity * b.costPerUnit), 0)                       AS REAL) as invCost,
          CAST(COALESCE(SUM(b.quantity * COALESCE(b.sellingPrice, b.costPerUnit)),0) AS REAL) as invRetail,
          CAST(COALESCE(SUM(b.quantity), 0)                                       AS REAL) as inStockUnits,
          COUNT(*)                                                                         as batchCount
        FROM VetMedicineBatch b
        WHERE b.status = 'active' AND b.quantity > 0 AND b.expiryDate >= ?
      `, now);
      const expiredRows = await prisma2.$queryRawUnsafe(`
        SELECT CAST(COALESCE(SUM(b.quantity * b.costPerUnit), 0) AS REAL) as expiredCost
        FROM VetMedicineBatch b
        WHERE b.status = 'active' AND b.quantity > 0 AND b.expiryDate < ?
      `, now);
      const perMed = await prisma2.$queryRawUnsafe(`
        SELECT m.id, m.name, m.unit,
          CAST(COALESCE(SUM(${ACTUAL}), 0)         AS REAL)    as actualRevenue,
          CAST(COALESCE(SUM(${EQTY} * ${LISTED}), 0) AS REAL)  as expectedRevenue,
          CAST(COALESCE(SUM(${EQTY} * b.costPerUnit), 0) AS REAL) as cogs,
          CAST(COALESCE(SUM(${EQTY}), 0)            AS REAL)    as unitsSold
        FROM VetMedicineSale s
        JOIN VetMedicineBatch b ON s.batchId = b.id
        JOIN VetMedicine m      ON s.medicineId = m.id
        WHERE s.saleDate >= ? AND s.saleDate <= ?
          AND (s.status IS NULL OR s.status != 'refunded')
        GROUP BY m.id, m.name, m.unit
        ORDER BY actualRevenue DESC
        LIMIT 8
      `, from, to);
      const s = soldRows[0] ?? {};
      const actualRevenue = Number(s.actualRevenue) || 0;
      const expectedRevenue = Number(s.expectedRevenue) || 0;
      const cogs = Number(s.cogs) || 0;
      const actualProfit = actualRevenue - cogs;
      const expectedProfit = expectedRevenue - cogs;
      const inv = invRows[0] ?? {};
      const invCost = Number(inv.invCost) || 0;
      const invRetail = Number(inv.invRetail) || 0;
      const potentialProfit = invRetail - invCost;
      return {
        sales: {
          saleCount: Number(s.saleCount) || 0,
          unitsSold: Number(s.unitsSold) || 0,
          actualRevenue,
          expectedRevenue,
          cogs,
          actualProfit,
          expectedProfit,
          discountsGiven: Math.max(0, expectedRevenue - actualRevenue),
          actualMargin: actualRevenue > 0 ? actualProfit / actualRevenue * 100 : 0,
          expectedMargin: expectedRevenue > 0 ? expectedProfit / expectedRevenue * 100 : 0,
          realizationRate: expectedRevenue > 0 ? actualRevenue / expectedRevenue * 100 : 100
        },
        inventory: {
          cost: invCost,
          retail: invRetail,
          potentialProfit,
          potentialMargin: invRetail > 0 ? potentialProfit / invRetail * 100 : 0,
          inStockUnits: Number(inv.inStockUnits) || 0,
          batchCount: Number(inv.batchCount) || 0,
          expiredCost: Number(expiredRows[0]?.expiredCost) || 0
        },
        topMedicines: perMed.map((m) => {
          const aRev = Number(m.actualRevenue) || 0;
          const eRev = Number(m.expectedRevenue) || 0;
          const c = Number(m.cogs) || 0;
          return {
            id: m.id,
            name: m.name,
            unit: m.unit,
            unitsSold: Number(m.unitsSold) || 0,
            actualRevenue: aRev,
            expectedRevenue: eRev,
            actualProfit: aRev - c,
            expectedProfit: eRev - c,
            discountsGiven: Math.max(0, eRev - aRev)
          };
        })
      };
    } catch (err) {
      log96.error("profitAnalysis", err);
      throw err;
    }
  });
  ipcMain.handle("vet:stats:salesBreakdown", async (_e, params) => {
    try {
      const now = /* @__PURE__ */ new Date();
      const from = params?.from ? new Date(params.from) : new Date(now.getFullYear(), now.getMonth(), 1);
      const to = params?.to ? new Date(params.to) : now;
      const EQTY = SQL_SOLD_QTY;
      const ACTUAL = SQL_NET_REVENUE;
      const ACTIVE = `(s.status IS NULL OR s.status != 'refunded')`;
      const byCategory = await prisma2.$queryRawUnsafe(`
        SELECT m.category                                            as category,
          COUNT(*)                                                   as saleCount,
          CAST(COALESCE(SUM(${EQTY}), 0)              AS REAL)       as units,
          CAST(COALESCE(SUM(${ACTUAL}), 0)            AS REAL)       as revenue,
          CAST(COALESCE(SUM(${EQTY} * b.costPerUnit), 0) AS REAL)    as cogs
        FROM VetMedicineSale s
        JOIN VetMedicineBatch b ON s.batchId = b.id
        JOIN VetMedicine m      ON s.medicineId = m.id
        WHERE s.saleDate >= ? AND s.saleDate <= ? AND ${ACTIVE}
        GROUP BY m.category
        ORDER BY revenue DESC
      `, from, to);
      const byPayment = await prisma2.$queryRawUnsafe(`
        SELECT COALESCE(NULLIF(s.paymentMethod, ''), 'unknown')      as method,
          COUNT(*)                                                   as saleCount,
          CAST(COALESCE(SUM(s.totalPrice - COALESCE(s.refundedAmount,0)), 0) AS REAL) as revenue
        FROM VetMedicineSale s
        WHERE s.saleDate >= ? AND s.saleDate <= ? AND (s.status IS NULL OR s.status != 'refunded')
        GROUP BY method
        ORDER BY revenue DESC
      `, from, to);
      const refundRows = await prisma2.$queryRawUnsafe(`
        SELECT COUNT(*)                                              as refundCount,
          CAST(COALESCE(SUM(COALESCE(s.refundedAmount,0)), 0) AS REAL) as refundAmount
        FROM VetMedicineSale s
        WHERE s.saleDate >= ? AND s.saleDate <= ?
          AND (s.status IN ('refunded','partially_refunded') OR COALESCE(s.refundedAmount,0) > 0)
      `, from, to);
      return {
        byCategory: byCategory.map((c) => {
          const revenue = Number(c.revenue) || 0;
          const cogs = Number(c.cogs) || 0;
          return {
            category: c.category || "general",
            saleCount: Number(c.saleCount) || 0,
            units: Number(c.units) || 0,
            revenue,
            profit: revenue - cogs
          };
        }),
        byPayment: byPayment.map((p) => ({
          method: p.method || "unknown",
          saleCount: Number(p.saleCount) || 0,
          revenue: Number(p.revenue) || 0
        })),
        refunds: {
          count: Number(refundRows[0]?.refundCount) || 0,
          amount: Number(refundRows[0]?.refundAmount) || 0
        }
      };
    } catch (err) {
      log96.error("salesBreakdown", err);
      throw err;
    }
  });
}

// src/plugins/vet/handlers/stats.inventory.ts
init_electron_node();
var log97 = createLogger("Vet:Stats:Inventory");
function registerVetStatsInventoryHandlers(prisma2) {
  ipcMain.handle("vet:stats:inventoryTurnover", async (_e, params) => {
    try {
      const to = params?.to ? new Date(params.to) : /* @__PURE__ */ new Date();
      const from = params?.from ? new Date(params.from) : new Date((/* @__PURE__ */ new Date()).getFullYear(), (/* @__PURE__ */ new Date()).getMonth(), 1);
      const periodDays = Math.max(1, Math.round((to.getTime() - from.getTime()) / 864e5));
      const now = /* @__PURE__ */ new Date();
      const in30 = new Date(now.getTime() + 30 * 864e5);
      const stockRows = await prisma2.$queryRawUnsafe(`
        SELECT m.id, m.name, m.unit, m.category,
          CAST(COALESCE(SUM(b.quantity * b.costPerUnit), 0) AS REAL) as stockValue,
          CAST(COALESCE(SUM(b.quantity), 0) AS REAL)                 as stockUnits
        FROM VetMedicine m
        LEFT JOIN VetMedicineBatch b ON b.medicineId = m.id AND b.status = 'active'
        GROUP BY m.id, m.name, m.unit, m.category
      `);
      const saleRows = await prisma2.$queryRawUnsafe(`
        SELECT m.id,
          CAST(COALESCE(SUM(${SQL_COGS}), 0) AS REAL)         as cogs,
          CAST(COALESCE(SUM(${SQL_SOLD_QTY}), 0) AS REAL)     as unitsSold,
          CAST(COALESCE(SUM(${SQL_NET_REVENUE}), 0) AS REAL)  as revenue,
          COUNT(*)                                            as saleCount,
          MAX(s.saleDate)                                     as lastSold
        FROM VetMedicineSale s
        JOIN VetMedicineBatch b ON s.batchId = b.id
        JOIN VetMedicine m      ON s.medicineId = m.id
        WHERE s.saleDate >= ? AND s.saleDate <= ?
          AND (s.status IS NULL OR s.status != 'refunded')
        GROUP BY m.id
      `, from, to);
      const saleById = new Map(saleRows.map((r) => [r.id, r]));
      const annualise = 365 / periodDays;
      const items = stockRows.map((s) => {
        const sale = saleById.get(s.id) ?? {};
        const stockValue = Number(s.stockValue) || 0;
        const cogs = Number(sale.cogs) || 0;
        const unitsSold = Number(sale.unitsSold) || 0;
        const revenue = Number(sale.revenue) || 0;
        const dailyCogs2 = cogs / periodDays;
        const turnover = stockValue > 0 ? cogs * annualise / stockValue : 0;
        const daysOnHand = dailyCogs2 > 0 ? stockValue / dailyCogs2 : null;
        const dead = stockValue > 0 && cogs <= 0;
        return {
          id: s.id,
          name: s.name,
          unit: s.unit,
          category: s.category,
          stockValue,
          stockUnits: Number(s.stockUnits) || 0,
          cogs,
          unitsSold,
          revenue,
          saleCount: Number(sale.saleCount) || 0,
          lastSold: sale.lastSold ?? null,
          turnover,
          daysOnHand,
          dead
        };
      });
      const healthRows = await prisma2.$queryRawUnsafe(`
        SELECT
          CAST(COALESCE(SUM(CASE WHEN b.expiryDate < ? THEN b.quantity * b.costPerUnit ELSE 0 END), 0) AS REAL) as expiredValue,
          CAST(COALESCE(SUM(CASE WHEN b.expiryDate >= ? AND b.expiryDate <= ? THEN b.quantity * b.costPerUnit ELSE 0 END), 0) AS REAL) as expiringValue
        FROM VetMedicineBatch b WHERE b.status = 'active'
      `, now, now, in30);
      const totalStockValue = items.reduce((a, x) => a + x.stockValue, 0);
      const totalCogs = items.reduce((a, x) => a + x.cogs, 0);
      const totalRevenue = items.reduce((a, x) => a + x.revenue, 0);
      const totalUnitsSold = items.reduce((a, x) => a + x.unitsSold, 0);
      const deadItems = items.filter((x) => x.dead && x.stockValue > 0);
      const dailyCogs = totalCogs / periodDays;
      return {
        periodDays,
        overall: {
          stockValue: totalStockValue,
          cogs: totalCogs,
          revenue: totalRevenue,
          unitsSold: totalUnitsSold,
          turnover: totalStockValue > 0 ? totalCogs * annualise / totalStockValue : 0,
          daysOnHand: dailyCogs > 0 ? totalStockValue / dailyCogs : null,
          deadStockValue: deadItems.reduce((a, x) => a + x.stockValue, 0),
          deadStockCount: deadItems.length,
          expiringValue: Number(healthRows[0]?.expiringValue) || 0,
          expiredValue: Number(healthRows[0]?.expiredValue) || 0,
          medicineCount: items.length,
          stockedCount: items.filter((x) => x.stockValue > 0).length
        },
        // Fastest movers first; medicines with stock but no sales (dead) sink.
        items: items.sort((a, b) => b.turnover - a.turnover)
      };
    } catch (err) {
      log97.error("inventoryTurnover", err);
      throw err;
    }
  });
}

